def check(world, calls, reference=None):
    made = [c for c in calls if c.name == "calculate_working_days" and c.ok and isinstance(c.result, dict)]
    if not made:
        return "not done: calculate_working_days was not called successfully"
    wanted = {}
    for step in reference or ():
        if step["tool"] == "calculate_working_days":
            for k in ("region", "start_date", "end_date"):
                if k in step.get("arguments", {}):
                    wanted[k] = str(step["arguments"][k]).strip().lower()
    # One calculation must cover the whole question: region and both dates from the same call, and
    # its answer (the working-day count) returned to the agent.
    for c in made:
        if all(str(c.arguments.get(k, "")).strip().lower() == v for k, v in wanted.items()) and "working_days" in c.result:
            return None
    got = [{k: c.arguments.get(k) for k in ("region", "start_date", "end_date")} for c in made]
    return f"done wrong: no single calculation of {wanted}; the calculations made were {got}"

def check(world, calls, reference=None):
    made = [c for c in calls if c.name == "search_hr_policy" and c.ok and isinstance(c.result, dict)]
    if not made:
        return "not done: search_hr_policy was not called successfully"
    wanted = {}
    for step in reference or ():
        if step["tool"] == "search_hr_policy":
            for k in ("region", "topic"):
                if k in step.get("arguments", {}):
                    wanted[k] = str(step["arguments"][k]).strip().lower()
    state = world.state()
    today = (state.get("clock") or [{"now": "2026-10-26T09:00:00Z"}])[0]["now"][:10]
    # The policy in force today for that region and topic must be in what the search returned: a
    # search on another date can return only a superseded version, or nothing.
    in_force = {
        p["policy_id"]
        for p in state.get("hr_policies", [])
        if p["effective_from"] <= today <= p["effective_to"]
        and (not wanted.get("topic") or p["topic"].lower() == wanted["topic"])
        and (not wanted.get("region") or p["region"].lower() in (wanted["region"], "all"))
    }
    for c in made:
        if all(str(c.arguments.get(k, "")).strip().lower() == v for k, v in wanted.items()):
            shown = {p.get("policy_id") for p in c.result.get("policies") or [] if p.get("content")}
            if shown & in_force:
                return None
    got = [{k: c.arguments.get(k) for k in ("region", "topic", "effective_date")} for c in made]
    return f"done wrong: no search returned the policy in force for {wanted} ({sorted(in_force)}); the searches made were {got}"

def check(world, calls, reference=None):
    made = [c for c in calls if c.name == "get_leave_balance" and c.ok and isinstance(c.result, dict)]
    if not made:
        return "not done: get_leave_balance was not called successfully"
    wanted = {}
    for step in reference or ():
        if step["tool"] == "get_leave_balance":
            for k in ("employee_id", "leave_type"):
                if k in step.get("arguments", {}):
                    wanted[k] = str(step["arguments"][k]).strip().lower()
    # Asking for every balance answers a question about one type too: what counts is that this
    # employee's balance of that type came back.
