        if wanted.get("employee_id") and str(c.arguments.get("employee_id", "")).strip().lower() != wanted["employee_id"]:
            continue
        types = {str(b.get("leave_type", "")).lower() for b in c.result.get("balances") or []}
        if (wanted.get("leave_type") in types) if wanted.get("leave_type") else types:
            return None
    got = [(c.arguments.get("employee_id"), c.arguments.get("leave_type")) for c in made]
    return f"done wrong: the {wanted.get('leave_type') or 'leave'} balance of {wanted.get('employee_id')} was never returned; the lookups made were {got}"

def check(world, calls, reference=None):
    made = [c for c in calls if c.name == "submit_leave_request" and c.ok]
    if not made:
        return "not done: submit_leave_request was not called successfully"
    state = world.state()
    now = (state.get("clock") or [{"now": ""}])[0]["now"]
    new = [r for r in state.get("leave_requests", []) if r.get("created_at") == now]
    if not new:
        return "not done: no leave request was recorded in the world by this run"
    wanted = {}
    for step in reference or ():
        if step["tool"] == "submit_leave_request":
            for k in ("employee_id", "leave_type", "start_date", "end_date"):
                if k in step.get("arguments", {}):
                    wanted[k] = step["arguments"][k]
    matching = [r for r in new if all(str(r.get(f, "")).strip().lower() == str(v).strip().lower() for f, v in wanted.items())]
    if not matching:
        return f"done wrong: no new leave request matched {wanted}; the run created {[(r['employee_id'], r['start_date'], r['end_date']) for r in new]}"
    if len(new) != 1:
        return f"done wrong: {len(new)} requests were created, the employee asked for one"
    if matching[0].get("status") != "pending":
        return f"done wrong: request status expected 'pending', got {matching[0].get('status')!r}"
    missing = _evidence_missing(world, calls, reference)
    if missing:
        return f"done blind: the decision rests on {', '.join(missing)}, which was never read"
    return None

def _evidence_missing(world, calls, reference):
    """The Slack thread or library document the reference fixes and whether its content reached this
    run: the text of every message in the thread (the desk's own posts aside) returned by a thread
    read, channel read or search, and the document read."""
    state = world.state()
    desk = (state.get("current_actor") or [{}])[0].get("user_id")
    wanted = []
    for step in reference or ():
        a = step.get("arguments", {})
        if step.get("tool") == "slack_read_thread" and a.get("message_ts"):
            wanted.append(("Slack thread", a["message_ts"]))
        elif step.get("tool") == "read_file_content" and a.get("fileId"):
            wanted.append(("file", a["fileId"]))
    texts = _texts_shown(calls)
    missing = []
    for kind, target in wanted:
        if kind == "Slack thread":
            needed = [m["ts"] for m in state.get("slack_messages", []) if (m["ts"] == target or m.get("thread_ts") == target) and m["user_id"] != desk]
            seen = bool(needed) and all(t in texts for t in needed)
        else:
            seen = any(c.ok and c.name == "read_file_content" and c.arguments.get("fileId") == target for c in calls)
        if not seen:
            missing.append(f"{kind} {target}")
    return missing


